/// <summary>
/// FFI-facing mirror of [`crate::core::CoreError`] (hello-gate / identity
/// failures). Mapped 1:1 in [`From<CoreErrorImpl>`].
/// </summary>
public class CoreException: UniffiException {
    CoreException() : base() {}
    CoreException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// The hello signature did not verify against the peer's public key (or
    /// the signature is not valid base64url / not 64 bytes).
    /// </summary>
    public class InvalidHelloSignature : CoreException {
        public InvalidHelloSignature() : base() {}
    }
    
    
    /// <summary>
    /// The `(peer_id, nonce)` pair was already accepted.
    /// </summary>
    public class NonceReplay : CoreException {
        public NonceReplay() : base() {}
    }
    
    
    /// <summary>
    /// Handshake-level failure (protocol version, peer id binding, …).
    /// </summary>
    
    public class HandshakeFailed : CoreException {
        // Members
        public string @reason;

        // Constructor
        public HandshakeFailed(
                string @reason) : base(
                "@reason" + "=" + @reason) {

            this.@reason = @reason;
        }
    }
    
    /// <summary>
    /// The hello nonce does not satisfy the wire constraints (minLength 16).
    /// </summary>
    
    public class InvalidNonce : CoreException {
        // Members
        public string @message;

        // Constructor
        public InvalidNonce(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// Cryptography-level failure (invalid key bytes, base64 decoding, …).
    /// </summary>
    
    public class Crypto : CoreException {
        // Members
        public string @message;

        // Constructor
        public Crypto(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// RFC 8785 JCS canonicalization / serialization of the signed object
    /// failed.
    /// </summary>
    
    public class Jcs : CoreException {
        // Members
        public string @message;

        // Constructor
        public Jcs(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    
    /// <summary>
    /// A capability-token proof failed validation (malformed shape, bad
    /// signature, untrusted issuer, subject/audience/expiry mismatch, or
    /// claim-rule violation).
    /// </summary>
    
    public class TokenInvalid : CoreException {
        // Members
        public string @message;

        // Constructor
        public TokenInvalid(
                string @message) : base(
                "@message" + "=" + @message) {

            this.@message = @message;
        }
    }
    

    
}

public class FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException>, CallStatusErrorHandler<CoreException> {
    public static FfiConverterTypeCoreError INSTANCE = new FfiConverterTypeCoreError();

    public override CoreException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CoreException.InvalidHelloSignature();
            case 2:
                return new CoreException.NonceReplay();
            case 3:
                return new CoreException.HandshakeFailed(
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new CoreException.InvalidNonce(
                    FfiConverterString.INSTANCE.Read(stream));
            case 5:
                return new CoreException.Crypto(
                    FfiConverterString.INSTANCE.Read(stream));
            case 6:
                return new CoreException.Jcs(
                    FfiConverterString.INSTANCE.Read(stream));
            case 7:
                return new CoreException.TokenInvalid(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Read()", value));
        }
    }

    public override int AllocationSize(CoreException value) {
        switch (value) {

            case CoreException.InvalidHelloSignature variant_value:
                return 4;

            case CoreException.NonceReplay variant_value:
                return 4;

            case CoreException.HandshakeFailed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@reason);

            case CoreException.InvalidNonce variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.Crypto variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.Jcs variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);

            case CoreException.TokenInvalid variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@message);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.AllocationSize()", value));
        }
    }

    public override void Write(CoreException value, BigEndianStream stream) {
        switch (value) {
            case CoreException.InvalidHelloSignature variant_value:
                stream.WriteInt(1);
                break;
            case CoreException.NonceReplay variant_value:
                stream.WriteInt(2);
                break;
            case CoreException.HandshakeFailed variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@reason, stream);
                break;
            case CoreException.InvalidNonce variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.Crypto variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.Jcs variant_value:
                stream.WriteInt(6);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            case CoreException.TokenInvalid variant_value:
                stream.WriteInt(7);
                FfiConverterString.INSTANCE.Write(variant_value.@message, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreError.Write()", value));
        }
    }
}





/// <summary>
/// FFI-facing mirror of [`crate::core::CoreInvokeError`] (invoke-path
/// sequence / correlation failures). Mapped 1:1 in
/// [`From<CoreInvokeErrorImpl>`].
/// </summary>
public class CoreInvokeException: UniffiException {
    CoreInvokeException() : base() {}
    CoreInvokeException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// The session's outbound sequence space (2⁵³−1) is exhausted; the
    /// session must be closed and reopened — sequences never wrap.
    /// </summary>
    public class SequenceExhausted : CoreInvokeException {
        public SequenceExhausted() : base() {}
    }
    
    
    /// <summary>
    /// An inbound invoke `sequence` is not the next expected one (replay or
    /// out-of-order); the invoke must not be dispatched.
    /// </summary>
    
    public class InboundSequenceMismatch : CoreInvokeException {
        // Members
        public ulong @expected;
        public long @actual;

        // Constructor
        public InboundSequenceMismatch(
                ulong @expected, 
                long @actual) : base(
                "@expected" + "=" + @expected+ ", " +
                "@actual" + "=" + @actual) {

            this.@expected = @expected;

            this.@actual = @actual;
        }
    }
    
    /// <summary>
    /// A response did not echo the request's `session_id` / `sequence` /
    /// `request_id`.
    /// </summary>
    public class CorrelationMismatch : CoreInvokeException {
        public CorrelationMismatch() : base() {}
    }
    
    

    
}

public class FfiConverterTypeCoreInvokeError : FfiConverterRustBuffer<CoreInvokeException>, CallStatusErrorHandler<CoreInvokeException> {
    public static FfiConverterTypeCoreInvokeError INSTANCE = new FfiConverterTypeCoreInvokeError();

    public override CoreInvokeException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new CoreInvokeException.SequenceExhausted();
            case 2:
                return new CoreInvokeException.InboundSequenceMismatch(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterInt64.INSTANCE.Read(stream));
            case 3:
                return new CoreInvokeException.CorrelationMismatch();
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreInvokeError.Read()", value));
        }
    }

    public override int AllocationSize(CoreInvokeException value) {
        switch (value) {

            case CoreInvokeException.SequenceExhausted variant_value:
                return 4;

            case CoreInvokeException.InboundSequenceMismatch variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@expected)
                    + FfiConverterInt64.INSTANCE.AllocationSize(variant_value.@actual);

            case CoreInvokeException.CorrelationMismatch variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreInvokeError.AllocationSize()", value));
        }
    }

    public override void Write(CoreInvokeException value, BigEndianStream stream) {
        switch (value) {
            case CoreInvokeException.SequenceExhausted variant_value:
                stream.WriteInt(1);
                break;
            case CoreInvokeException.InboundSequenceMismatch variant_value:
                stream.WriteInt(2);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@expected, stream);
                FfiConverterInt64.INSTANCE.Write(variant_value.@actual, stream);
                break;
            case CoreInvokeException.CorrelationMismatch variant_value:
                stream.WriteInt(3);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeCoreInvokeError.Write()", value));
        }
    }
}




public class FfiConverterOptionalString: FfiConverterRustBuffer<string?> {
    public static FfiConverterOptionalString INSTANCE = new FfiConverterOptionalString();

    public override string? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterString.INSTANCE.Read(stream);
    }

    public override int AllocationSize(string? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterString.INSTANCE.AllocationSize((string)value);
        }
    }

    public override void Write(string? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterString.INSTANCE.Write((string)value, stream);
        }
    }
}




public class FfiConverterSequenceString: FfiConverterRustBuffer<string[]> {
    public static FfiConverterSequenceString INSTANCE = new FfiConverterSequenceString();

    public override string[]  Read(BigEndianStream stream) {
        var length = stream.ReadInt();
        if (length == 0) {
            return [];
        }

        var result = new string[length];
        var readFn = FfiConverterString.INSTANCE.Read;
        for (int i = 0; i < length; i++) {
            result[i] = readFn(stream);
        }
        return result;
    }

    public override int AllocationSize(string[]  value) {
        var sizeForLength = 4;

        // details/1-empty-list-as-default-method-parameter.md
        if (value == null) {
            return sizeForLength;
        }

        var allocationSizeFn = FfiConverterString.INSTANCE.AllocationSize;
        var sizeForItems = value.Sum(item => allocationSizeFn(item));
        return sizeForLength + sizeForItems;
    }

    public override void Write(string[] value, BigEndianStream stream) {
        // details/1-empty-list-as-default-method-parameter.md
        if (value == null) {
            stream.WriteInt(0);
            return;
        }

        stream.WriteInt(value.Length);
        var writerFn = FfiConverterString.INSTANCE.Write;
        value.ForEach(item => writerFn(item, stream));
    }
}
